export default function solve(params) {
  const t0 = Date.now();
  const HARD = 540000;
  const T_MAIN = 491000;
  const T_FINAL = 524500;
  const N = 26;
  const GAP = 2e-9;
  const LAM = 3.0;
  const trace = [];
  let best = null;
  let lastBeat = 0;
  let hbT = 0;
  let seed = 246813579;
  function rnd() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
  function rand(a, b) { return a + (b - a) * rnd(); }
  function gauss() {
    let u = 0;
    while (u === 0) u = rnd();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307179586 * rnd());
  }
  function ri(k) { return (rnd() * k) | 0; }

  const BESTCFG = [[0.273986930157,0.105564777918,0.105564775918],[0.084779588079,0.08477958689,0.08477958489],[0.906096993543,0.500125404591,0.093902547628],[0.483008460079,0.103457986825,0.103457984825],[0.383728484432,0.703199613053,0.114230299314],[0.084728280398,0.915277629652,0.084722368348],[0.483414340869,0.896626722808,0.103373275192],[0.596552021416,0.27278748303,0.100416039061],[0.763208096221,0.24037738997,0.069353126852],[0.74235936656,0.595999324418,0.095838903319],[0.682625981771,0.904029619918,0.095970378082],[0.273485364826,0.50091916972,0.116140971148],[0.682387668434,0.096056687311,0.096056685311],[0.132268564044,0.29656207406,0.13226194022],[0.889034453607,0.889039733739,0.110960264261],[0.596872496933,0.727510393795,0.100276141458],[0.382652378098,0.297342085633,0.114859166238],[0.888955747332,0.111038273033,0.111038271033],[0.742295763154,0.404280728643,0.095878920407],[0.53078333267,0.500268239281,0.13638136101],[0.907500889276,0.313729033078,0.092499108724],[0.27416059532,0.894111275138,0.105888722862],[0.131668250614,0.704083836192,0.131624987386],[0.763353450919,0.759806901541,0.069308525485],[0.907549226566,0.686473067572,0.092450771434],[0.078672343857,0.500573636461,0.078672341855]];

  function makeState() {
    return {
      X: new Float64Array(N), Y: new Float64Array(N), R: new Float64Array(N),
      gx: new Float64Array(N), gy: new Float64Array(N), gr: new Float64Array(N),
      mx: new Float64Array(N), vx: new Float64Array(N),
      my: new Float64Array(N), vy: new Float64Array(N),
      mr: new Float64Array(N), vr: new Float64Array(N)
    };
  }
  function loadFrom(dst, src) { dst.X.set(src.X); dst.Y.set(src.Y); dst.R.set(src.R); }
  function clampC(st2, i, m) {
    if (st2.X[i] < m) st2.X[i] = m; else if (st2.X[i] > 1 - m) st2.X[i] = 1 - m;
    if (st2.Y[i] < m) st2.Y[i] = m; else if (st2.Y[i] > 1 - m) st2.Y[i] = 1 - m;
  }

  function evalGrad(X, Y, R, gx, gy, gr, lam, rmin) {
    let F = 0;
    gx.fill(0); gy.fill(0); gr.fill(0);
    for (let i = 0; i < N; i++) {
      const x = X[i], y = Y[i];
      F -= R[i]; gr[i] -= 1;
      let w = x, a = 0;
      if (1 - x < w) { w = 1 - x; a = 1; }
      if (y < w) { w = y; a = 2; }
      if (1 - y < w) { w = 1 - y; a = 3; }
      let v = R[i] - w;
      if (v > 0) {
        F += lam * v; gr[i] += lam;
        if (a === 0) gx[i] -= lam; else if (a === 1) gx[i] += lam;
        else if (a === 2) gy[i] -= lam; else gy[i] += lam;
      }
      v = rmin - R[i];
      if (v > 0) { F += lam * v; gr[i] -= lam; }
    }
    for (let i = 0; i < N; i++) {
      const xi = X[i], yi = Y[i], rI = R[i];
      for (let j = i + 1; j < N; j++) {
        const dx = xi - X[j], dy = yi - Y[j];
        let d = Math.sqrt(dx * dx + dy * dy);
        if (d < 1e-12) d = 1e-12;
        const v = rI + R[j] - d;
        if (v > 0) {
          F += lam * v;
          const s = lam / d;
          gx[i] -= dx * s; gy[i] -= dy * s;
          gx[j] += dx * s; gy[j] += dy * s;
          gr[i] += lam; gr[j] += lam;
        }
      }
    }
    return F;
  }

  function adamOpt(st, steps, lr0, lr1, lam, rmin, radiiOnly) {
    const X = st.X, Y = st.Y, R = st.R, gx = st.gx, gy = st.gy, gr = st.gr;
    const mx = st.mx, vx = st.vx, my = st.my, vy = st.vy, mr = st.mr, vr = st.vr;
    const b1 = 0.9, b2 = 0.99, eps = 1e-8;
    let c1 = 1, c2 = 1;
    mx.fill(0); vx.fill(0); my.fill(0); vy.fill(0); mr.fill(0); vr.fill(0);
    const ratio = Math.log(lr1 / lr0);
    for (let t = 1; t <= steps; t++) {
      const lr = lr0 * Math.exp(ratio * (t / steps));
      evalGrad(X, Y, R, gx, gy, gr, lam, rmin);
      c1 *= b1; c2 *= b2;
      const ic1 = 1 / (1 - c1), ic2 = 1 / (1 - c2);
      if (!radiiOnly) {
        for (let i = 0; i < N; i++) {
          let g = gx[i];
          mx[i] = b1 * mx[i] + (1 - b1) * g;
          vx[i] = b2 * vx[i] + (1 - b2) * g * g;
          X[i] -= lr * (mx[i] * ic1) / (Math.sqrt(vx[i] * ic2) + eps);
          if (X[i] < 0) X[i] = 0; else if (X[i] > 1) X[i] = 1;
          g = gy[i];
          my[i] = b1 * my[i] + (1 - b1) * g;
          vy[i] = b2 * vy[i] + (1 - b2) * g * g;
          Y[i] -= lr * (my[i] * ic1) / (Math.sqrt(vy[i] * ic2) + eps);
          if (Y[i] < 0) Y[i] = 0; else if (Y[i] > 1) Y[i] = 1;
        }
      }
      for (let i = 0; i < N; i++) {
        const g = gr[i];
        mr[i] = b1 * mr[i] + (1 - b1) * g;
        vr[i] = b2 * vr[i] + (1 - b2) * g * g;
        R[i] -= lr * (mr[i] * ic1) / (Math.sqrt(vr[i] * ic2) + eps);
        if (R[i] < 0.0005) R[i] = 0.0005; else if (R[i] > 0.5) R[i] = 0.5;
      }
      if ((t & 511) === 0 && Date.now() - t0 > T_FINAL - 1500) return;
    }
  }

  function growSnap(X, Y, R, gap, passes) {
    for (let p = 0; p < passes; p++) {
      let moved = false;
      for (let i = 0; i < N; i++) {
        let lim = Math.min(X[i], 1 - X[i], Y[i], 1 - Y[i]) - gap;
        for (let j = 0; j < N; j++) {
          if (j === i) continue;
          const dx = X[i] - X[j], dy = Y[i] - Y[j];
          const a = Math.sqrt(dx * dx + dy * dy) - R[j] - gap;
          if (a < lim) lim = a;
        }
        if (lim > R[i]) { R[i] = lim; moved = true; }
      }
      if (!moved) break;
    }
  }

  function shrinkRepair(X, Y, R, gap) {
    for (let i = 0; i < N; i++) {
      const wmax = Math.min(X[i], 1 - X[i], Y[i], 1 - Y[i]) - gap;
      if (R[i] > wmax) R[i] = wmax > 1e-9 ? wmax : 1e-9;
    }
    for (let it2 = 0; it2 < 300; it2++) {
      let any = false;
      for (let i = 0; i < N; i++) {
        for (let j = i + 1; j < N; j++) {
          const dx = X[i] - X[j], dy = Y[i] - Y[j];
          const d = Math.sqrt(dx * dx + dy * dy);
          const allowed = d - gap;
          const sum = R[i] + R[j];
          if (sum > allowed) {
            const excess = sum - allowed;
            if (sum > 1e-12) {
              const s = R[i] / sum;
              R[i] -= excess * s;
              R[j] -= excess * (1 - s);
            } else { R[i] = allowed * 0.5; R[j] = allowed * 0.5; }
            if (R[i] < 1e-9) R[i] = 1e-9;
            if (R[j] < 1e-9) R[j] = 1e-9;
            any = true;
          }
        }
      }
      if (!any) break;
    }
  }

  function minSlack(X, Y, R) {
    let m = Infinity;
    for (let i = 0; i < N; i++) {
      if (R[i] < m) m = R[i];
      let s = X[i] - R[i]; if (s < m) m = s;
      s = 1 - X[i] - R[i]; if (s < m) m = s;
      s = Y[i] - R[i]; if (s < m) m = s;
      s = 1 - Y[i] - R[i]; if (s < m) m = s;
      for (let j = i + 1; j < N; j++) {
        const dx = X[i] - X[j], dy = Y[i] - Y[j];
        const v = Math.sqrt(dx * dx + dy * dy) - R[i] - R[j];
        if (v < m) m = v;
      }
    }
    return m;
  }

  const pairsList = [];
  for (let i2 = 0; i2 < N; i2++) for (let j2 = i2 + 1; j2 < N; j2++) pairsList.push(i2 * 64 + j2);
  const NP = pairsList.length;
  const NV = NP + N;
  const smD = new Float64Array(NV);
  const smB = new Float64Array(676);
  const smCb = new Float64Array(26);
  const smXb = new Float64Array(26);
  const smPi = new Float64Array(26);
  const smU = new Float64Array(26);
  const bType = new Int32Array(26);
  const bIdx = new Int32Array(26);
  const smR = new Float64Array(N);
  const smYv = new Float64Array(NV);
  const colE = new Float64Array(26);
  const inBasisPair = new Int8Array(NP);
  const inBasisWall = new Int8Array(N);
  const inBasisSur = new Int8Array(N);
  const gX = new Float64Array(N);
  const gY = new Float64Array(N);
  const sX0 = new Float64Array(N);
  const sY0 = new Float64Array(N);
  const ONE26 = new Float64Array(26);
  for (let q0 = 0; q0 < 26; q0++) ONE26[q0] = 1;

  function solveLin(M, b, x, tr) {
    const A = new Float64Array(676);
    const b2 = new Float64Array(26);
    if (tr) {
      for (let r2 = 0; r2 < 26; r2++) for (let c2 = 0; c2 < 26; c2++) A[r2 * 26 + c2] = M[c2 * 26 + r2];
    } else A.set(M);
    b2.set(b);
    for (let c = 0; c < 26; c++) {
      let piv = c, bv = Math.abs(A[c * 26 + c]);
      for (let r2 = c + 1; r2 < 26; r2++) { const v = Math.abs(A[r2 * 26 + c]); if (v > bv) { bv = v; piv = r2; } }
      if (bv < 1e-13) return false;
      if (piv !== c) {
        for (let c2 = c; c2 < 26; c2++) { const tmp = A[c * 26 + c2]; A[c * 26 + c2] = A[piv * 26 + c2]; A[piv * 26 + c2] = tmp; }
        const tb = b2[c]; b2[c] = b2[piv]; b2[piv] = tb;
      }
      const inv = 1 / A[c * 26 + c];
      for (let r2 = c + 1; r2 < 26; r2++) {
        const f = A[r2 * 26 + c] * inv;
        if (f === 0) continue;
        for (let c2 = c + 1; c2 < 26; c2++) A[r2 * 26 + c2] -= f * A[c * 26 + c2];
        b2[r2] -= f * b2[c];
      }
    }
    for (let r2 = 25; r2 >= 0; r2--) {
      let s = b2[r2];
      for (let c2 = r2 + 1; c2 < 26; c2++) s -= A[r2 * 26 + c2] * x[c2];
      x[r2] = s / A[r2 * 26 + r2];
    }
    return true;
  }

  function solveRadiiSimplex(X, Y, WF) {
    const F = WF || ONE26;
    for (let k = 0; k < NP; k++) {
      const pk = pairsList[k], i = pk >> 6, j = pk & 63;
      const dx = X[i] - X[j], dy = Y[i] - Y[j];
      smD[k] = Math.sqrt(dx * dx + dy * dy);
    }
    for (let i = 0; i < N; i++) {
      let w = X[i];
      if (1 - X[i] < w) w = 1 - X[i];
      if (Y[i] < w) w = Y[i];
      if (1 - Y[i] < w) w = 1 - Y[i];
      smD[NP + i] = w;
    }
    for (let k = 0; k < 26; k++) { bType[k] = 1; bIdx[k] = k; }
    let prevObj = Infinity, conv = false;
    for (let iter = 0; iter < 900; iter++) {
      smB.fill(0);
      inBasisPair.fill(0); inBasisWall.fill(0); inBasisSur.fill(0);
      for (let j = 0; j < 26; j++) {
        const ty = bType[j], ix = bIdx[j];
        if (ty === 0) {
          const pk = pairsList[ix];
          smB[(pk >> 6) * 26 + j] = 1;
          smB[(pk & 63) * 26 + j] = 1;
          smCb[j] = smD[ix];
          inBasisPair[ix] = 1;
        } else if (ty === 1) {
          smB[ix * 26 + j] = 1;
          smCb[j] = smD[NP + ix];
          inBasisWall[ix] = 1;
        } else {
          smB[ix * 26 + j] = -1;
          smCb[j] = 0;
          inBasisSur[ix] = 1;
        }
      }
      if (!solveLin(smB, F, smXb, false)) return -1;
      if (!solveLin(smB, smCb, smPi, true)) return -1;
      let obj = 0;
      for (let j = 0; j < 26; j++) obj += smCb[j] * smXb[j];
      if (obj > prevObj + 1e-8) return -1;
      prevObj = obj;
      let bestRc = -1e-10, eT = -1, eI = -1;
      for (let k = 0; k < NP; k++) {
        if (inBasisPair[k]) continue;
        const pk = pairsList[k];
        const rc = smD[k] - smPi[pk >> 6] - smPi[pk & 63];
        if (rc < bestRc) { bestRc = rc; eT = 0; eI = k; }
      }
      for (let i = 0; i < N; i++) {
        if (!inBasisWall[i] && !inBasisSur[i]) {
          const rc = smD[NP + i] - smPi[i];
          if (rc < bestRc) { bestRc = rc; eT = 1; eI = i; }
        }
        if (!inBasisSur[i] && !inBasisWall[i]) {
          const rc = smPi[i];
          if (rc < bestRc) { bestRc = rc; eT = 2; eI = i; }
        }
      }
      if (eT < 0) { conv = true; break; }
      colE.fill(0);
      if (eT === 0) { const pk = pairsList[eI]; colE[pk >> 6] = 1; colE[pk & 63] = 1; }
      else if (eT === 1) colE[eI] = 1;
      else colE[eI] = -1;
      if (!solveLin(smB, colE, smU, false)) return -1;
      let lvr = Infinity, lv = -1;
      for (let k = 0; k < 26; k++) {
        if (smU[k] > 1e-11) {
          const rt = smXb[k] / smU[k];
          if (rt < lvr - 1e-12) { lvr = rt; lv = k; }
        }
      }
      if (lv < 0) return -1;
      bType[lv] = eT; bIdx[lv] = eI;
    }
    if (!conv) return -1;
    smYv.fill(0);
    for (let j = 0; j < 26; j++) {
      if (bType[j] === 0) smYv[bIdx[j]] = smXb[j];
      else if (bType[j] === 1) smYv[NP + bIdx[j]] = smXb[j];
    }
    for (let i = 0; i < N; i++) {
      let v = smPi[i];
      if (v < 1e-9) v = 1e-9;
      smR[i] = v;
    }
    shrinkRepair(X, Y, smR, 0);
    let s = 0;
    for (let i = 0; i < N; i++) s += F[i] * smR[i];
    return s;
  }

  function polishSimplex(st2, maxMs, WF) {
    const tend = Math.min(Date.now() + Math.max(0, maxMs), t0 + HARD);
    for (let i = 0; i < N; i++) clampC(st2, i, 1e-6);
    let val = solveRadiiSimplex(st2.X, st2.Y, WF);
    if (val < 0) return -1;
    let alpha = 2e-3;
    let fails = 0;
    while (Date.now() < tend) {
      gX.fill(0); gY.fill(0);
      for (let k = 0; k < NP; k++) {
        const yk = smYv[k];
        if (yk <= 1e-11) continue;
        const pk = pairsList[k], i = pk >> 6, j = pk & 63;
        const dx = st2.X[i] - st2.X[j], dy = st2.Y[i] - st2.Y[j];
        let d = Math.sqrt(dx * dx + dy * dy); if (d < 1e-12) d = 1e-12;
        const ux = dx / d * yk, uy = dy / d * yk;
        gX[i] += ux; gY[i] += uy; gX[j] -= ux; gY[j] -= uy;
      }
      for (let i = 0; i < N; i++) {
        const yk = smYv[NP + i];
        if (yk <= 1e-11) continue;
        let w = st2.X[i], a = 0;
        if (1 - st2.X[i] < w) { w = 1 - st2.X[i]; a = 1; }
        if (st2.Y[i] < w) { w = st2.Y[i]; a = 2; }
        if (1 - st2.Y[i] < w) { w = 1 - st2.Y[i]; a = 3; }
        if (a === 0) gX[i] += yk; else if (a === 1) gX[i] -= yk;
        else if (a === 2) gY[i] += yk; else gY[i] -= yk;
      }
      let ng = 0;
      for (let i = 0; i < N; i++) ng += gX[i] * gX[i] + gY[i] * gY[i];
      ng = Math.sqrt(ng);
      if (ng < 1e-10) break;
      sX0.set(st2.X); sY0.set(st2.Y);
      let a2 = alpha, val2 = val, improved = false, stop = false;
      for (let ls = 0; ls < 22; ls++) {
        const scp = a2 / ng;
        for (let i = 0; i < N; i++) {
          st2.X[i] = sX0[i] + gX[i] * scp;
          st2.Y[i] = sY0[i] + gY[i] * scp;
          clampC(st2, i, 1e-6);
        }
        if (Date.now() > tend) { stop = true; break; }
        const v2 = solveRadiiSimplex(st2.X, st2.Y, WF);
        if (v2 > val + 1e-13) { improved = true; val2 = v2; break; }
        a2 *= 0.5;
      }
      if (improved) {
        val = val2;
        alpha = a2 * 1.4; if (alpha > 0.03) alpha = 0.03;
        fails = 0;
      } else {
        st2.X.set(sX0); st2.Y.set(sY0);
        alpha = a2 * 0.3;
        fails++;
        if (stop || alpha < 1e-11 || fails > 30) break;
      }
    }
    const vf2 = solveRadiiSimplex(st2.X, st2.Y, WF);
    if (vf2 >= 0) { st2.R.set(smR); return vf2; }
    return -1;
  }

  function probeV(st2, ms) {
    const tend = Math.min(Date.now() + Math.max(0, ms), t0 + HARD);
    let val = solveRadiiSimplex(st2.X, st2.Y);
    if (val < 0) return -1;
    while (Date.now() < tend) {
      sX0.set(st2.X); sY0.set(st2.Y);
      const m = rnd();
      if (m < 0.52) {
        const k = 1 + ri(3);
        const sig = Math.exp(rand(Math.log(2e-4), Math.log(2.6e-2)));
        for (let c = 0; c < k; c++) {
          const i = ri(N);
          st2.X[i] += gauss() * sig; st2.Y[i] += gauss() * sig;
          clampC(st2, i, 1e-6);
        }
      } else if (m < 0.68) {
        const i = ri(N);
        let w = st2.X[i], a = 0;
        if (1 - st2.X[i] < w) { w = 1 - st2.X[i]; a = 1; }
        if (st2.Y[i] < w) { w = st2.Y[i]; a = 2; }
        if (1 - st2.Y[i] < w) { w = 1 - st2.Y[i]; a = 3; }
        const f = rand(0.08, 0.75) * Math.max(0, w - st2.R[i]);
        if (a === 0) st2.X[i] -= f; else if (a === 1) st2.X[i] += f;
        else if (a === 2) st2.Y[i] -= f; else st2.Y[i] += f;
        clampC(st2, i, 1e-6);
      } else if (m < 0.84) {
        let cx = 0, cy = 0;
        for (let i = 0; i < N; i++) { cx += st2.X[i]; cy += st2.Y[i]; }
        cx /= N; cy /= N;
        const sc2 = rand(0.985, 1.015);
        for (let i = 0; i < N; i++) {
          st2.X[i] = cx + (st2.X[i] - cx) * sc2;
          st2.Y[i] = cy + (st2.Y[i] - cy) * sc2;
          clampC(st2, i, 1e-6);
        }
      } else {
        let cx = 0, cy = 0;
        for (let i = 0; i < N; i++) { cx += st2.X[i]; cy += st2.Y[i]; }
        cx /= N; cy /= N;
        const r0 = rand(0, 0.3), r1 = r0 + rand(0.1, 0.35), th = rand(-0.35, 0.35);
        const co = Math.cos(th), si = Math.sin(th);
        for (let i = 0; i < N; i++) {
          const dx = st2.X[i] - cx, dy = st2.Y[i] - cy;
          const rr = Math.sqrt(dx * dx + dy * dy);
          if (rr >= r0 && rr <= r1) {
            st2.X[i] = cx + dx * co - dy * si;
            st2.Y[i] = cy + dx * si + dy * co;
            clampC(st2, i, 1e-6);
          }
        }
      }
      const v2 = solveRadiiSimplex(st2.X, st2.Y);
      if (v2 >= 0 && v2 > val + 1e-12) { val = v2; }
      else { st2.X.set(sX0); st2.Y.set(sY0); }
    }
    const vf = solveRadiiSimplex(st2.X, st2.Y);
    if (vf >= 0) { st2.R.set(smR); return vf; }
    return val;
  }

  function hillClimb(st2, ms) {
    const tend = Math.min(t0 + HARD, Date.now() + Math.max(60, ms));
    let v = polishSimplex(st2, Math.max(80, (tend - Date.now()) * 0.55));
    if (v < 0) return -1;
    let guard = 0;
    while (Date.now() < tend - 40 && guard < 24) {
      guard++;
      const pv = probeV(st2, Math.min(140, Math.max(40, (tend - Date.now()) * 0.45)));
      if (pv < 0) break;
      if (pv > v + 1e-10) {
        const v2 = polishSimplex(st2, Math.max(60, tend - Date.now()));
        if (v2 > v) { v = v2; continue; }
      }
      break;
    }
    if (Date.now() < tend) {
      const vf = polishSimplex(st2, Math.max(50, tend - Date.now()));
      if (vf > v) v = vf;
    }
    return v;
  }

  function considerBest(st2) {
    const v = solveRadiiSimplex(st2.X, st2.Y);
    const Xc = new Float64Array(st2.X), Yc = new Float64Array(st2.Y);
    const Rc = new Float64Array(N);
    if (v >= 0) { Rc.set(smR); } else { Rc.set(st2.R); }
    shrinkRepair(Xc, Yc, Rc, GAP);
    growSnap(Xc, Yc, Rc, GAP, 10);
    shrinkRepair(Xc, Yc, Rc, GAP);
    let s = 0;
    for (let i = 0; i < N; i++) s += Rc[i];
    if (!best || s > best.score) {
      best = { X: Xc, Y: Yc, R: Rc, score: s };
      lastBeat = Date.now() - t0;
      trace.push([+((lastBeat / 1000).toFixed(3)), s]);
    }
    return s;
  }

  const elites = [];
  function addEliteEntry(st2, sc) {
    for (let e = 0; e < elites.length; e++) {
      const el = elites[e];
      let md = 0;
      for (let i = 0; i < N; i++) md += Math.abs(el.X[i] - st2.X[i]) + Math.abs(el.Y[i] - st2.Y[i]);
      md /= N;
      if (md < 0.01 && Math.abs(el.score - sc) < 1e-4) {
        if (sc > el.score) { el.X.set(st2.X); el.Y.set(st2.Y); el.R.set(st2.R); el.score = sc; }
        return;
      }
    }
    elites.push({ X: new Float64Array(st2.X), Y: new Float64Array(st2.Y), R: new Float64Array(st2.R), score: sc });
    elites.sort(function (x1, x2) { return x2.score - x1.score; });
    if (elites.length > 16) elites.length = 16;
  }

  function collectCandidates(st2, skip, nU, nP, nH, take) {
    take = take || 6;
    const scores = [];
    const pts = [];
    function addCand(x, y) {
      if (x < 1e-4 || x > 1 - 1e-4 || y < 1e-4 || y > 1 - 1e-4) return;
      let cl = x;
      if (1 - x < cl) cl = 1 - x;
      if (y < cl) cl = y;
      if (1 - y < cl) cl = 1 - y;
      for (let j = 0; j < N; j++) {
        if (j === skip) continue;
        const dx = x - st2.X[j], dy = y - st2.Y[j];
        const d = Math.sqrt(dx * dx + dy * dy) - st2.R[j];
        if (d < cl) cl = d;
      }
      pts.push(x); pts.push(y); scores.push(cl);
    }
    for (let s = 0; s < nU; s++) addCand(rnd(), rnd());
    for (let s = 0; s < nP; s++) {
      const j = ri(N), k = ri(N);
      if (j === k || j === skip || k === skip) continue;
      const dx = st2.X[k] - st2.X[j], dy = st2.Y[k] - st2.Y[j];
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d < 1e-9) continue;
      const gl = d - st2.R[j] - st2.R[k];
      const off = (rnd() - 0.5) * Math.max(0.015, gl);
      addCand((st2.X[j] + st2.X[k]) * 0.5 - dy / d * off, (st2.Y[j] + st2.Y[k]) * 0.5 + dx / d * off);
    }
    for (let s = 0; s < (nH || 0); s++) {
      const a = ri(N), b2 = ri(N), c2 = ri(N);
      if (a === b2 || a === c2 || b2 === c2 || a === skip || b2 === skip || c2 === skip) continue;
      let px = (st2.X[a] + st2.X[b2] + st2.X[c2]) / 3 + gauss() * 0.012;
      let py = (st2.Y[a] + st2.Y[b2] + st2.Y[c2]) / 3 + gauss() * 0.012;
      if (px < 1e-4) px = 1e-4; else if (px > 1 - 1e-4) px = 1 - 1e-4;
      if (py < 1e-4) py = 1e-4; else if (py > 1 - 1e-4) py = 1 - 1e-4;
      let bx = px, by = py, bc = -1e9, step = 0.02;
      for (let it = 0; it < 26; it++) {
        let cc = px, gx2 = 1, gy2 = 0;
        if (1 - px < cc) { cc = 1 - px; gx2 = -1; gy2 = 0; }
        if (py < cc) { cc = py; gx2 = 0; gy2 = 1; }
        if (1 - py < cc) { cc = 1 - py; gx2 = 0; gy2 = -1; }
        for (let j = 0; j < N; j++) {
          if (j === skip) continue;
          const dx = px - st2.X[j], dy = py - st2.Y[j];
          let dd = Math.sqrt(dx * dx + dy * dy);
          const d = dd - st2.R[j];
          if (d < cc) { cc = d; if (dd < 1e-12) dd = 1e-12; gx2 = dx / dd; gy2 = dy / dd; }
        }
        let moved2 = false;
        let stp = step;
        for (let tr2 = 0; tr2 < 3; tr2++) {
          let qx = px + gx2 * stp, qy = py + gy2 * stp;
          if (qx < 1e-4) qx = 1e-4; else if (qx > 1 - 1e-4) qx = 1 - 1e-4;
          if (qy < 1e-4) qy = 1e-4; else if (qy > 1 - 1e-4) qy = 1 - 1e-4;
          let cq = qx; if (1 - qx < cq) cq = 1 - qx; if (qy < cq) cq = qy; if (1 - qy < cq) cq = 1 - qy;
          for (let j = 0; j < N; j++) {
            if (j === skip) continue;
            const dx = qx - st2.X[j], dy = qy - st2.Y[j];
            const d = Math.sqrt(dx * dx + dy * dy) - st2.R[j];
            if (d < cq) cq = d;
          }
          if (cq > cc) { px = qx; py = qy; if (cq > bc) { bc = cq; bx = qx; by = qy; } moved2 = true; break; }
          stp *= 0.35;
        }
        if (moved2) { if (step < 0.02) step *= 1.4; } else step *= 0.5;
        if (step < 2e-5) break;
      }
      addCand(bx, by);
    }
    const m = scores.length;
    const out = [];
    const used = new Uint8Array(m);
    for (let t = 0; t < take && t < m; t++) {
      let bi = -1, bv = -Infinity;
      for (let q = 0; q < m; q++) { if (!used[q] && scores[q] > bv) { bv = scores[q]; bi = q; } }
      if (bi < 0) break;
      used[bi] = 1;
      out.push([pts[bi * 2], pts[bi * 2 + 1]]);
    }
    return out;
  }

  let sweepPtr = 0;
  const st = makeState();
  const cur = makeState();
  let curScore = -1;

  function sweepStep(ms, idxForced) {
    if (idxForced === undefined) idxForced = -1;
    const tend = Date.now() + ms;
    loadFrom(st, best);
    const v0 = solveRadiiSimplex(st.X, st.Y);
    if (v0 < 0) return;
    st.R.set(smR);
    const order = new Array(N);
    for (let i = 0; i < N; i++) order[i] = i;
    let i;
    if (idxForced >= 0) { i = idxForced; }
    else if (rnd() < 0.3) {
      order.sort(function (a2, b2) { return smPi[b2] - smPi[a2]; });
      i = order[ri(6)];
      sweepPtr++;
    } else {
      order.sort(function (a2, b2) { return st.R[a2] - st.R[b2]; });
      i = order[sweepPtr % N];
      sweepPtr++;
    }
    const cands = collectCandidates(st, i, 170, 60, 24, 8);
    let bestV = v0, bx = st.X[i], by = st.Y[i];
    for (let c = 0; c < cands.length; c++) {
      if (Date.now() > tend) break;
      st.X[i] = cands[c][0];
      st.Y[i] = cands[c][1];
      const v = solveRadiiSimplex(st.X, st.Y);
      if (v >= 0 && v > bestV + 3e-7) { bestV = v; bx = cands[c][0]; by = cands[c][1]; }
    }
    st.X[i] = bx;
    st.Y[i] = by;
    if (bestV > v0 - 2.5e-3) {
      const pb = best.score;
      if (tend - Date.now() > 60) hillClimb(st, Math.min(340, tend - Date.now()));
      const sc = considerBest(st);
      if (sc > best.score - 3e-3) addEliteEntry(st, sc);
      if (best.score <= pb) loadFrom(st, best);
    } else {
      st.X[i] = best.X[i];
      st.Y[i] = best.Y[i];
    }
  }

  function bottleneckShift(budget) {
    if (!best) return;
    const tend = Math.min(Date.now() + budget, t0 + HARD);
    loadFrom(st, best);
    const v0 = solveRadiiSimplex(st.X, st.Y);
    if (v0 < 0) return;
    st.R.set(smR);
    const order = new Array(N);
    for (let i = 0; i < N; i++) order[i] = i;
    order.sort(function (a2, b2) { return smPi[b2] - smPi[a2]; });
    const i = order[ri(5)];
    const cands = collectCandidates(st, i, 120, 80, 30, 10);
    let bestV = v0, bx = st.X[i], by = st.Y[i];
    for (let c = 0; c < cands.length; c++) {
      if (Date.now() > tend) break;
      st.X[i] = cands[c][0];
      st.Y[i] = cands[c][1];
      const v = solveRadiiSimplex(st.X, st.Y);
      if (v >= 0 && v > bestV + 2e-7) { bestV = v; bx = cands[c][0]; by = cands[c][1]; }
    }
    st.X[i] = bx;
    st.Y[i] = by;
    if (bestV > v0 - 2.5e-3 && tend - Date.now() > 60) {
      hillClimb(st, Math.min(300, tend - Date.now()));
      const sc = considerBest(st);
      if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    }
    loadFrom(st, best);
  }

  function displaceK(st2, amp, k) {
    for (let c = 0; c < k; c++) {
      const i = ri(N);
      st2.X[i] += gauss() * amp; st2.Y[i] += gauss() * amp;
      clampC(st2, i, 0.02);
    }
  }
  function jitterAll(st2, amp) {
    for (let i = 0; i < N; i++) {
      st2.X[i] += gauss() * amp; st2.Y[i] += gauss() * amp;
      clampC(st2, i, 0.02);
    }
  }
  function rotateBand(st2) {
    let cx = 0, cy = 0;
    for (let i = 0; i < N; i++) { cx += st2.X[i]; cy += st2.Y[i]; }
    cx /= N; cy /= N;
    const r0 = rand(0, 0.22), r1 = r0 + rand(0.12, 0.34);
    const th = rand(-0.9, 0.9), c = Math.cos(th), s = Math.sin(th);
    for (let i = 0; i < N; i++) {
      const dx = st2.X[i] - cx, dy = st2.Y[i] - cy;
      const rr = Math.sqrt(dx * dx + dy * dy);
      if (rr >= r0 && rr <= r1) {
        st2.X[i] = cx + dx * c - dy * s;
        st2.Y[i] = cy + dx * s + dy * c;
        clampC(st2, i, 0.02);
      }
    }
  }
  function nudgeSegment(st2, amp) {
    const ang = rand(0, 6.283185307179586), nx = Math.cos(ang), ny = Math.sin(ang);
    const t = rand(0.15, 0.85);
    const dxs = gauss() * amp, dys = gauss() * amp;
    for (let i = 0; i < N; i++) {
      if (st2.X[i] * nx + st2.Y[i] * ny > t) {
        st2.X[i] += dxs; st2.Y[i] += dys;
        clampC(st2, i, 0.02);
      }
    }
  }
  function compressStretch(st2) {
    let cx = 0, cy = 0;
    for (let i = 0; i < N; i++) { cx += st2.X[i]; cy += st2.Y[i]; }
    cx /= N; cy /= N;
    const s = rnd() < 0.55 ? rand(0.968, 0.9985) : rand(1.0015, 1.028);
    for (let i = 0; i < N; i++) {
      st2.X[i] = cx + (st2.X[i] - cx) * s;
      st2.Y[i] = cy + (st2.Y[i] - cy) * s;
      clampC(st2, i, 0.02);
    }
  }
  function relocateWeakest(st2) {
    let a = -1, b = -1, c = -1;
    for (let i = 0; i < N; i++) {
      const r = st2.R[i];
      if (a < 0 || r < st2.R[a]) { c = b; b = a; a = i; }
      else if (b < 0 || r < st2.R[b]) { c = b; b = i; }
      else if (c < 0 || r < st2.R[c]) { c = i; }
    }
    const pick = [a, b, c][ri(3)];
    const cands = collectCandidates(st2, pick, 160, 30, 36, 8);
    if (cands.length === 0) return;
    const ch = cands[0];
    st2.X[pick] = ch[0]; st2.Y[pick] = ch[1];
    let cl = Math.min(ch[0], 1 - ch[0], ch[1], 1 - ch[1]);
    for (let j = 0; j < N; j++) {
      if (j === pick) continue;
      const dx = ch[0] - st2.X[j], dy = ch[1] - st2.Y[j];
      const d = Math.sqrt(dx * dx + dy * dy) - st2.R[j];
      if (d < cl) cl = d;
    }
    st2.R[pick] = Math.max(0.02, Math.min(cl * 0.8, 0.2));
  }

  function screenBurst(budget) {
    if (!best) return;
    const tend = Math.min(Date.now() + budget, t0 + HARD);
    const cand = [];
    let g = 0;
    const nSrc = Math.min(elites.length, 6);
    while (Date.now() < tend - 350 && g < 20) {
      g++;
      if (nSrc > 0 && rnd() < 0.55) { const el = elites[ri(nSrc)]; st.X.set(el.X); st.Y.set(el.Y); st.R.set(el.R); }
      else { st.X.set(best.X); st.Y.set(best.Y); st.R.set(best.R); }
      const m = rnd();
      if (m < 0.30) displaceK(st, Math.exp(rand(Math.log(0.02), Math.log(0.13))), 2 + ri(4));
      else if (m < 0.44) rotateBand(st);
      else if (m < 0.57) nudgeSegment(st, rand(0.03, 0.08));
      else if (m < 0.69) compressStretch(st);
      else if (m < 0.85) jitterAll(st, rand(0.012, 0.05));
      else relocateWeakest(st);
      const v = solveRadiiSimplex(st.X, st.Y);
      if (v < 0) continue;
      if (v > best.score - 0.012) cand.push({ X: new Float64Array(st.X), Y: new Float64Array(st.Y), v: v, taken: 0 });
    }
    cand.sort(function (a2, b2) { return b2.v - a2.v; });
    let taken = 0;
    for (let c = 0; c < cand.length && taken < 3; c++) {
      if (Date.now() > tend - 220) break;
      let dup = false;
      for (let t2 = 0; t2 < c; t2++) {
        if (!cand[t2].taken) continue;
        let md = 0;
        for (let i = 0; i < N; i++) md += Math.abs(cand[t2].X[i] - cand[c].X[i]) + Math.abs(cand[t2].Y[i] - cand[c].Y[i]);
        md /= N;
        if (md < 0.018) { dup = true; break; }
      }
      if (dup) continue;
      cand[c].taken = 1; taken++;
      st.X.set(cand[c].X); st.Y.set(cand[c].Y); st.R.fill(0.05);
      hillClimb(st, Math.min(500, Math.max(80, tend - Date.now())));
      const sc = considerBest(st);
      if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    }
    loadFrom(st, best);
  }

  function ruinRecreate(budget) {
    if (!best) return;
    const tend = Date.now() + budget;
    loadFrom(st, best);
    const sel = new Int32Array(9);
    const kept = new Uint8Array(N);
    let ns = 0, cxp = 0.5, cyp = 0.5, rad = 0.2;
    for (let tries = 0; tries < 16; tries++) {
      cxp = rand(0.08, 0.92); cyp = rand(0.08, 0.92);
      rad = rand(0.11, 0.36);
      ns = 0;
      for (let i = 0; i < N; i++) {
        const dx = st.X[i] - cxp, dy = st.Y[i] - cyp;
        if (dx * dx + dy * dy < rad * rad) ns++;
      }
      if (ns >= 2 && ns <= 9) break;
      ns = 0;
    }
    if (ns < 2) return;
    kept.fill(1);
    let cnt = 0;
    for (let i = 0; i < N; i++) {
      const dx = st.X[i] - cxp, dy = st.Y[i] - cyp;
      if (dx * dx + dy * dy < rad * rad && cnt < 9) { kept[i] = 0; sel[cnt++] = i; }
    }
    for (let a = cnt - 1; a > 0; a--) { const b2 = ri(a + 1); const tt = sel[a]; sel[a] = sel[b2]; sel[b2] = tt; }
    const greedy = rnd() < 0.65;
    const tmpX = new Float64Array(9), tmpY = new Float64Array(9);
    for (let q = 0; q < cnt; q++) {
      const i = sel[q];
      if (greedy) {
        let bx = 0.5, by = 0.5, bcl = -Infinity;
        for (let s2 = 0; s2 < 90; s2++) {
          let px, py;
          if (s2 < 60) { px = rnd(); py = rnd(); }
          else {
            const a2 = ri(N), b2 = ri(N);
            if (a2 === b2) continue;
            px = (st.X[a2] + st.X[b2]) * 0.5 + (rnd() - 0.5) * 0.04;
            py = (st.Y[a2] + st.Y[b2]) * 0.5 + (rnd() - 0.5) * 0.04;
          }
          if (px < 1e-4 || px > 1 - 1e-4 || py < 1e-4 || py > 1 - 1e-4) continue;
          let cl = Math.min(px, 1 - px, py, 1 - py);
          for (let j = 0; j < N; j++) {
            if (!kept[j]) continue;
            const dx = px - st.X[j], dy = py - st.Y[j];
            const d = Math.sqrt(dx * dx + dy * dy) - st.R[j];
            if (d < cl) cl = d;
          }
          for (let q2 = 0; q2 < q; q2++) {
            const dx = px - tmpX[q2], dy = py - tmpY[q2];
            const d = Math.sqrt(dx * dx + dy * dy) - 0.085;
            if (d < cl) cl = d;
          }
          if (cl > bcl) { bcl = cl; bx = px; by = py; }
        }
        st.X[i] = bx + gauss() * 0.004;
        st.Y[i] = by + gauss() * 0.004;
      } else {
        st.X[i] = cxp + gauss() * rad * 0.45;
        st.Y[i] = cyp + gauss() * rad * 0.45;
      }
      clampC(st, i, 1e-6);
      tmpX[q] = st.X[i]; tmpY[q] = st.Y[i];
    }
    hillClimb(st, Math.max(120, tend - Date.now()));
    const sc = considerBest(st);
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    if (sc < best.score - 2e-3) loadFrom(st, best);
  }

  function dihed(x, y, tf) {
    switch (tf) {
      case 0: return [x, y];
      case 1: return [1 - x, y];
      case 2: return [x, 1 - y];
      case 3: return [1 - x, 1 - y];
      case 4: return [y, x];
      case 5: return [y, 1 - x];
      case 6: return [1 - y, x];
      default: return [1 - y, 1 - x];
    }
  }

  function crossover(budget) {
    if (!best) return;
    const tend = Date.now() + budget;
    const pool = [];
    if (rnd() < 0.5) pool.push(best);
    for (let e = 0; e < Math.min(elites.length, 8); e++) pool.push(elites[e]);
    if (pool.length === 0) return;
    const eA = pool[ri(pool.length)];
    let eB = pool[ri(pool.length)];
    let g2 = 0;
    while (pool.length > 1 && eB === eA && g2 < 6) { eB = pool[ri(pool.length)]; g2++; }
    const tf = ri(8);
    const bx = new Float64Array(N), by = new Float64Array(N);
    for (let i = 0; i < N; i++) { const p = dihed(eB.X[i], eB.Y[i], tf); bx[i] = p[0]; by[i] = p[1]; }
    const ang = rand(0, Math.PI), nx = Math.cos(ang), ny = Math.sin(ang);
    const k = 5 + ri(17);
    const idxA = new Int32Array(N), idxB = new Int32Array(N);
    const pA = new Float64Array(N), pB = new Float64Array(N);
    for (let i = 0; i < N; i++) {
      idxA[i] = i; idxB[i] = i;
      pA[i] = eA.X[i] * nx + eA.Y[i] * ny;
      pB[i] = bx[i] * nx + by[i] * ny;
    }
    idxA.sort(function (a2, b2) { return pA[b2] - pA[a2]; });
    idxB.sort(function (a2, b2) { return pB[a2] - pB[b2]; });
    let c = 0;
    for (let t = 0; t < k; t++) { st.X[c] = eA.X[idxA[t]]; st.Y[c] = eA.Y[idxA[t]]; c++; }
    for (let t = 0; t < N - k; t++) { st.X[c] = bx[idxB[t]]; st.Y[c] = by[idxB[t]]; c++; }
    for (let i = 0; i < N; i++) st.R[i] = 0.05;
    adamOpt(st, 3200, 4e-3, 5e-4, LAM, 0.004, false);
    hillClimb(st, Math.max(120, tend - Date.now()));
    const sc = considerBest(st);
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    else loadFrom(st, best);
  }

  function hillClimbW(st2, ms, WF) {
    const tend = Math.min(t0 + HARD, Date.now() + Math.max(60, ms));
    let v = polishSimplex(st2, Math.max(70, (tend - Date.now()) * 0.6), WF);
    if (v < 0) return -1;
    let guard = 0;
    while (Date.now() < tend - 30 && guard < 8) {
      guard++;
      const v2 = polishSimplex(st2, Math.max(40, tend - Date.now()), WF);
      if (v2 >= v) v = v2; else break;
    }
    return v;
  }

  function pHomotopy(budget) {
    if (!best) return;
    const tend = Date.now() + budget;
    loadFrom(st, best);
    const W = new Float64Array(N);
    const ps = [0.45, 0.65, 0.85];
    for (let s2 = 0; s2 < 3; s2++) {
      if (Date.now() > tend - 60) break;
      const v = solveRadiiSimplex(st.X, st.Y);
      if (v < 0) return;
      for (let i = 0; i < N; i++) {
        const r = smR[i] > 1e-6 ? smR[i] : 1e-6;
        W[i] = Math.pow(r, ps[s2] - 1);
      }
      hillClimbW(st, Math.max(80, (tend - Date.now()) * 0.35), W);
    }
    hillClimb(st, Math.max(80, tend - Date.now()));
    const sc = considerBest(st);
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    else loadFrom(st, best);
  }

  function swapMove(budget) {
    if (!best) return;
    const tend = Date.now() + budget;
    loadFrom(st, best);
    const i = ri(N);
    let j = ri(N);
    if (j === i) j = (j + 1) % N;
    const xi = st.X[i], yi = st.Y[i];
    const amp = Math.exp(rand(Math.log(0.004), Math.log(0.03)));
    st.X[i] = st.X[j] + gauss() * amp; st.Y[i] = st.Y[j] + gauss() * amp;
    st.X[j] = xi + gauss() * amp; st.Y[j] = yi + gauss() * amp;
    clampC(st, i, 1e-6); clampC(st, j, 1e-6);
    hillClimb(st, Math.max(120, tend - Date.now()));
    const sc = considerBest(st);
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    else loadFrom(st, best);
  }

  function kickClimb() {
    const nowMs = Date.now() - t0;
    const since = nowMs - lastBeat;
    const ampMul = since > 140000 ? 2.6 : (since > 80000 ? 1.9 : (since > 40000 ? 1.35 : 1.0));
    const b = rnd();
    if (b < 0.62 || elites.length === 0) loadFrom(st, best);
    else if (b < 0.82) { const el = elites[ri(Math.min(elites.length, 8))]; loadFrom(st, el); }
    else loadFrom(st, cur);
    const m = rnd();
    let heavy = false;
    if (m < 0.24) { relocateWeakest(st); heavy = true; }
    else if (m < 0.58) { displaceK(st, Math.exp(rand(Math.log(0.005), Math.log(0.08))) * ampMul, 1 + ri(4)); }
    else if (m < 0.70) { jitterAll(st, rand(0.004, 0.018) * ampMul); }
    else if (m < 0.80) { rotateBand(st); }
    else if (m < 0.88) { nudgeSegment(st, 0.035 * ampMul); }
    else if (m < 0.94) { compressStretch(st); }
    else { displaceK(st, rand(0.02, 0.05) * ampMul, N); heavy = true; }
    if (heavy && rnd() < 0.5) adamOpt(st, 1400, 3e-3, 4e-4, LAM, 0.004, false);
    hillClimb(st, rand(160, 520));
    let sc = considerBest(st);
    if (sc > best.score - 8e-5 && rnd() < 0.7) {
      hillClimb(st, 1200);
      sc = considerBest(st);
    }
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    if (sc >= curScore - 6e-4 || rnd() < 0.06) { loadFrom(cur, st); curScore = sc; }
    if (curScore < best.score - 8e-3) { loadFrom(cur, best); curScore = best.score; }
  }

  function saRun(ms) {
    const tend = Math.min(t0 + HARD, Date.now() + Math.max(500, ms));
    const b = rnd();
    if (b < 0.62 || elites.length === 0) loadFrom(st, best);
    else if (b < 0.88) { const el = elites[ri(Math.min(elites.length, 8))]; loadFrom(st, el); }
    else loadFrom(st, cur);
    let val = solveRadiiSimplex(st.X, st.Y);
    if (val < 0) return;
    st.R.set(smR);
    let vAnchor = solveRadiiSimplex(best.X, best.Y);
    if (vAnchor < 0) vAnchor = best.score;
    const pbMark = best.score;
    const T0 = rand(7e-4, 2.4e-3), T1 = rand(3e-6, 3e-5);
    const tStart = Date.now();
    let steps = 0, sinceDeep = 100, climbs = 0;
    let lastClimbVal = val;
    while (Date.now() < tend) {
      steps++; sinceDeep++;
      const nowHb = Date.now() - t0;
      if (nowHb - hbT > 6000) { hbT = nowHb; trace.push([+(nowHb / 1000).toFixed(2), best.score]); }
      let frac = (Date.now() - tStart) / (tend - tStart);
      if (frac > 1) frac = 1;
      const T = T0 * Math.pow(T1 / T0, frac);
      sX0.set(st.X); sY0.set(st.Y);
      const m = rnd();
      if (m < 0.50) {
        const sig = Math.exp(rand(Math.log(3e-4), Math.log(0.03)));
        const k = 1 + ri(3);
        for (let c = 0; c < k; c++) {
          const i = ri(N);
          st.X[i] += gauss() * sig; st.Y[i] += gauss() * sig;
          clampC(st, i, 1e-6);
        }
      } else if (m < 0.63) {
        const i = ri(N);
        const cands = collectCandidates(st, i, 60, 20);
        if (cands.length > 0) { st.X[i] = cands[0][0]; st.Y[i] = cands[0][1]; }
      } else if (m < 0.73) {
        const i = ri(N);
        let j = -1, bd = Infinity;
        for (let q = 0; q < N; q++) {
          if (q === i) continue;
          const dx = st.X[i] - st.X[q], dy = st.Y[i] - st.Y[q];
          const d2 = dx * dx + dy * dy;
          if (d2 < bd) { bd = d2; j = q; }
        }
        if (j >= 0) {
          const mx2 = gauss() * 0.02, my2 = gauss() * 0.02;
          st.X[i] += mx2; st.Y[i] += my2;
          st.X[j] += mx2; st.Y[j] += my2;
          clampC(st, i, 1e-6); clampC(st, j, 1e-6);
        }
      } else if (m < 0.90) {
        let cx = 0, cy = 0;
        for (let i = 0; i < N; i++) { cx += st.X[i]; cy += st.Y[i]; }
        cx /= N; cy /= N;
        const r0 = rand(0, 0.25), r1 = r0 + rand(0.1, 0.3), th = rand(-0.3, 0.3);
        const co = Math.cos(th), si = Math.sin(th);
        for (let i = 0; i < N; i++) {
          const dx = st.X[i] - cx, dy = st.Y[i] - cy;
          const rr = Math.sqrt(dx * dx + dy * dy);
          if (rr >= r0 && rr <= r1) {
            st.X[i] = cx + dx * co - dy * si;
            st.Y[i] = cy + dx * si + dy * co;
            clampC(st, i, 1e-6);
          }
        }
      } else if (m < 0.93) {
        nudgeSegment(st, rand(0.01, 0.05));
        for (let i = 0; i < N; i++) clampC(st, i, 1e-6);
      } else {
        let cx = 0, cy = 0;
        for (let i = 0; i < N; i++) { cx += st.X[i]; cy += st.Y[i]; }
        cx /= N; cy /= N;
        const s2 = rand(0.988, 1.012);
        for (let i = 0; i < N; i++) {
          st.X[i] = cx + (st.X[i] - cx) * s2;
          st.Y[i] = cy + (st.Y[i] - cy) * s2;
          clampC(st, i, 1e-6);
        }
      }
      const v2 = solveRadiiSimplex(st.X, st.Y);
      if (v2 >= 0 && (v2 > val || rnd() < Math.exp((v2 - val) / T))) {
        val = v2;
        st.R.set(smR);
        if (val > best.score - 8e-5 && sinceDeep > 25 && climbs < 5 &&
            (val > lastClimbVal + 1e-6 || best.score > pbMark)) {
          climbs++;
          const pb2 = best.score;
          const hc = hillClimb(st, 380);
          if (hc > 0) {
            const scc = considerBest(st);
            if (scc > best.score - 3e-3) addEliteEntry(st, scc);
          }
          const vv = solveRadiiSimplex(st.X, st.Y);
          if (vv >= 0) { val = vv; st.R.set(smR); }
          lastClimbVal = val;
          sinceDeep = 0;
          if (best.score <= pb2 && val < best.score - 8e-5) {
            loadFrom(st, best);
            const v4 = solveRadiiSimplex(st.X, st.Y);
            if (v4 >= 0) { val = v4; st.R.set(smR); }
          }
        }
      } else {
        st.X.set(sX0); st.Y.set(sY0);
      }
      if ((steps & 1023) === 0 && val < vAnchor - 0.03) {
        loadFrom(st, best);
        const v4 = solveRadiiSimplex(st.X, st.Y);
        if (v4 >= 0) { val = v4; st.R.set(smR); }
      }
      if (Date.now() - t0 > T_FINAL - 900) break;
    }
  }

  function biasProbe() {
    loadFrom(st, best);
    const W = new Float64Array(N);
    for (let i = 0; i < N; i++) W[i] = 1;
    const nE = 1 + ri(2);
    for (let k = 0; k < nE; k++) { W[ri(N)] = rand(2.5, 6.5); }
    if (rnd() < 0.5) { W[ri(N)] = rand(0.3, 0.8); }
    hillClimbW(st, 240, W);
    hillClimb(st, 330);
    const sc = considerBest(st);
    if (sc > best.score - 3e-3) addEliteEntry(st, sc);
    else loadFrom(st, best);
  }

  function initLayout(st2, kind) {
    const X = st2.X, Y = st2.Y, R = st2.R;
    function clI(i) {
      if (X[i] < 0.04) X[i] = 0.04; else if (X[i] > 0.96) X[i] = 0.96;
      if (Y[i] < 0.04) Y[i] = 0.04; else if (Y[i] > 0.96) Y[i] = 0.96;
    }
    if (kind === 0) {
      for (let i = 0; i < N; i++) {
        const rad = 0.44 * Math.sqrt((i + 0.5) / N);
        const th = i * 2.399963229728653 + 0.3 * rnd();
        X[i] = 0.5 + rad * Math.cos(th);
        Y[i] = 0.5 + rad * Math.sin(th);
        R[i] = 0.06;
      }
    } else if (kind >= 1 && kind <= 4) {
      const layouts = [[6, 5, 6, 5, 4], [4, 6, 5, 6, 5], [5, 6, 5, 6, 4], [5, 5, 6, 5, 5]];
      const lay = layouts[kind - 1];
      const rows = lay.length;
      let c = 0;
      for (let k = 0; k < rows; k++) {
        const cnt = lay[k];
        const y = (k + 0.5) / rows;
        for (let j = 0; j < cnt; j++) {
          X[c] = (j + 1) / (cnt + 1) + gauss() * 0.008;
          Y[c] = y + gauss() * 0.008;
          R[c] = 0.065;
          c++;
        }
      }
    } else if (kind === 5) {
      X[0] = 0.5; Y[0] = 0.5; R[0] = 0.06;
      let c = 1;
      const r1 = 0.27, k1 = 8;
      for (let j = 0; j < k1; j++) {
        const th = (j / k1) * 6.283185307179586;
        X[c] = 0.5 + r1 * Math.cos(th); Y[c] = 0.5 + r1 * Math.sin(th); R[c] = 0.055; c++;
      }
      const k2 = N - c, r2 = 0.44;
      for (let j = 0; j < k2; j++) {
        const th = (j / k2) * 6.283185307179586 + 0.35;
        X[c] = 0.5 + r2 * Math.cos(th); Y[c] = 0.5 + r2 * Math.sin(th); R[c] = 0.05; c++;
      }
    } else if (kind === 7 || kind === 8) {
      const lay = kind === 7 ? [6, 5, 6, 5, 4] : [4, 6, 5, 6, 5];
      const cols = lay.length;
      let c = 0;
      for (let k = 0; k < cols; k++) {
        const cnt = lay[k];
        const x = (k + 0.5) / cols;
        for (let j = 0; j < cnt; j++) {
          X[c] = x + gauss() * 0.008;
          Y[c] = (j + 1) / (cnt + 1) + gauss() * 0.008;
          R[c] = 0.062;
          clI(c);
          c++;
        }
      }
    } else if (kind === 9) {
      const bx = 0.40 + gauss() * 0.03, by = 0.44 + gauss() * 0.03;
      X[0] = bx; Y[0] = by; R[0] = 0.075; clI(0);
      let c = 1;
      const k1 = 9, r1 = 0.25;
      for (let j = 0; j < k1; j++) {
        const th = (j / k1) * 6.283185307179586 + 0.2;
        X[c] = bx + r1 * Math.cos(th); Y[c] = by + r1 * Math.sin(th); R[c] = 0.05; clI(c); c++;
      }
      const k2 = 16, r2 = 0.46;
      for (let j = 0; j < k2; j++) {
        const th = (j / k2) * 6.283185307179586 + 0.45;
        X[c] = 0.5 + r2 * Math.cos(th); Y[c] = 0.5 + r2 * Math.sin(th); R[c] = 0.048; clI(c); c++;
      }
    } else if (kind === 10) {
      for (let i = 0; i < N; i++) {
        let bx2 = 0.5, by2 = 0.5, bc = -1e9;
        for (let t = 0; t < 60; t++) {
          const px = rand(0.07, 0.93), py = rand(0.07, 0.93);
          let cc = Math.min(px, 1 - px, py, 1 - py);
          for (let j = 0; j < i; j++) {
            const dx = px - X[j], dy = py - Y[j];
            const d = Math.sqrt(dx * dx + dy * dy) - 0.13;
            if (d < cc) cc = d;
          }
          if (cc > bc) { bc = cc; bx2 = px; by2 = py; }
        }
        X[i] = bx2 + gauss() * 0.004; Y[i] = by2 + gauss() * 0.004; R[i] = 0.05; clI(i);
      }
    } else if (kind === 11) {
      const d = 0.1;
      X[0] = d; Y[0] = d; R[0] = 0.07;
      X[1] = 1 - d; Y[1] = d; R[1] = 0.07;
      X[2] = d; Y[2] = 1 - d; R[2] = 0.07;
      X[3] = 1 - d; Y[3] = 1 - d; R[3] = 0.07;
      let c = 4;
      const k1 = 9, r1 = 0.245;
      for (let j = 0; j < k1; j++) {
        const th = (j / k1) * 6.283185307179586 + 0.13;
        X[c] = 0.5 + r1 * Math.cos(th); Y[c] = 0.5 + r1 * Math.sin(th); R[c] = 0.05; clI(c); c++;
      }
      const k2 = 13, r2 = 0.45;
      for (let j = 0; j < k2; j++) {
        const th = (j / k2) * 6.283185307179586 + 0.31;
        X[c] = 0.5 + r2 * Math.cos(th); Y[c] = 0.5 + r2 * Math.sin(th); R[c] = 0.048; clI(c); c++;
      }
    } else if (kind === 12) {
      const lay = [7, 6, 7, 6];
      const cols = 4;
      let c = 0;
      for (let k = 0; k < cols; k++) {
        const cnt = lay[k];
        const x = (k + 0.5) / cols;
        for (let j = 0; j < cnt; j++) {
          X[c] = x + gauss() * 0.006;
          Y[c] = (j + 1) / (cnt + 1) + gauss() * 0.006;
          R[c] = 0.06;
          clI(c);
          c++;
        }
      }
    } else {
      for (let i = 0; i < N; i++) { X[i] = rand(0.1, 0.9); Y[i] = rand(0.1, 0.9); R[i] = 0.05; }
    }
  }

  function restart() {
    initLayout(st, ri(13));
    adamOpt(st, 9000, 4.5e-3, 1.2e-4, LAM, 0.004, false);
    adamOpt(st, 2500, 1.2e-3, 4e-6, 8, 0.004, true);
    const vraw = solveRadiiSimplex(st.X, st.Y);
    if (vraw < 0) return;
    if (elites.length > 2) {
      let dup = false;
      for (let e = 0; e < elites.length; e++) {
        const el = elites[e];
        let md = 0;
        for (let i = 0; i < N; i++) md += Math.abs(el.X[i] - st.X[i]) + Math.abs(el.Y[i] - st.Y[i]);
        md /= N;
        if (md < 0.012 && vraw < el.score + 6e-4) { dup = true; break; }
      }
      if (dup) return;
    }
    const v = polishSimplex(st, 450);
    if (v < 0) return;
    let sc = considerBest(st);
    if (sc > best.score - 2.5e-3) {
      hillClimb(st, 420);
      sc = considerBest(st);
      addEliteEntry(st, sc);
    }
  }

  function finalize() {
    let X, Y, R;
    if (best) {
      X = new Float64Array(best.X);
      Y = new Float64Array(best.Y);
      R = new Float64Array(best.R);
    } else {
      X = new Float64Array(N); Y = new Float64Array(N); R = new Float64Array(N);
      for (let i = 0; i < N; i++) { X[i] = BESTCFG[i][0]; Y[i] = BESTCFG[i][1]; R[i] = BESTCFG[i][2] * 0.995; }
    }
    shrinkRepair(X, Y, R, GAP);
    growSnap(X, Y, R, GAP, 12);
    shrinkRepair(X, Y, R, GAP);
    let guard = 0;
    while (minSlack(X, Y, R) < 1.9e-9 && guard < 30) {
      for (let i = 0; i < N; i++) { R[i] -= 1.5e-9; if (R[i] < 1e-9) R[i] = 1e-9; }
      guard++;
    }
    let score = 0;
    const sol = [];
    for (let i = 0; i < N; i++) {
      if (R[i] < 1e-9) R[i] = 1e-9;
      score += R[i];
      sol.push([X[i], Y[i], R[i]]);
    }
    trace.push([+(((Date.now() - t0) / 1000).toFixed(2)), score]);
    return { solution: sol, trace: trace };
  }

  try {
    for (let i = 0; i < N; i++) { st.X[i] = BESTCFG[i][0]; st.Y[i] = BESTCFG[i][1]; st.R[i] = BESTCFG[i][2]; }
    considerBest(st);
    if (params) {
      let startPack = null;
      if (Array.isArray(params) && params.length === N && Array.isArray(params[0])) startPack = params;
      else if (params.solution && params.solution.length === N) startPack = params.solution;
      else if (params.start && params.start.length === N) startPack = params.start;
      else if (params.packing && params.packing.length === N) startPack = params.packing;
      if (startPack) {
        try {
          let ok = true;
          let sx = 0;
          for (let i = 0; i < N; i++) {
            const px = +startPack[i][0], py = +startPack[i][1], pr = +startPack[i][2];
            if (!(px >= 0 && px <= 1 && py >= 0 && py <= 1 && pr > 0)) ok = false;
            else { st.X[i] = px; st.Y[i] = py; st.R[i] = pr; sx += pr; }
          }
          if (ok && sx > (best ? best.score : 0)) considerBest(st);
        } catch (e2) { }
      }
    }
    loadFrom(st, best);
    let v0p = polishSimplex(st, 9000);
    if (v0p > 0) { considerBest(st); addEliteEntry(st, best.score); }
    probeV(st, 1500);
    considerBest(st);
    polishSimplex(st, 2500);
    considerBest(st);
    addEliteEntry(st, best.score);
    loadFrom(cur, best);
    curScore = best.score;

    while (Date.now() - t0 < T_MAIN) {
      const nowMs = Date.now() - t0;
      if (nowMs - hbT > 6000) { hbT = nowMs; trace.push([+(nowMs / 1000).toFixed(2), best.score]); }
      const u = rnd();
      if (u < 0.06) sweepStep(480);
      else if (u < 0.14) restart();
      else if (u < 0.20) kickClimb();
      else if (u < 0.27) biasProbe();
      else if (u < 0.31) pHomotopy(rand(1200, 2600));
      else if (u < 0.36) bottleneckShift(rand(500, 800));
      else if (u < 0.45) ruinRecreate(rand(1200, 2600));
      else if (u < 0.51) crossover(rand(1500, 2800));
      else if (u < 0.58) screenBurst(rand(1800, 3200));
      else saRun(rand(4500, 10000));
      if (Date.now() - t0 - lastBeat > 160000) { restart(); lastBeat = Date.now() - t0; }
    }

    let stagn = 0;
    while (Date.now() - t0 < T_FINAL - 1200) {
      const before = best.score;
      for (let c = 0; c < N; c++) {
        if (Date.now() - t0 > T_FINAL - 1000) break;
        sweepStep(400);
      }
      if (best.score > before + 1e-9) { stagn = 0; continue; }
      loadFrom(st, best);
      hillClimb(st, 600);
      considerBest(st);
      if (best.score > before + 1e-9) stagn = 0; else stagn++;
      if (stagn >= 3) {
        const w = rnd();
        if (w < 0.30) swapMove(620);
        else if (w < 0.50) ruinRecreate(1200);
        else if (w < 0.68) biasProbe();
        else if (w < 0.84) bottleneckShift(700);
        else screenBurst(1600);
        if (Date.now() - t0 < T_FINAL - 9000) saRun(Math.min(9000, T_FINAL - 2500 - (Date.now() - t0)));
        stagn = 0;
      }
    }
    loadFrom(st, best);
    considerBest(st);
  } catch (e3) { }

  return finalize();
}
